import assert from 'node:assert/strict'
import{chromium}from'playwright-core'
const browser=await chromium.launch({headless:true,executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',args:['--no-sandbox','--disable-gpu']})
const page=await browser.newPage({viewport:{width:1620,height:960}})
page.setDefaultTimeout(16000)
const errors=[];page.on('pageerror',e=>errors.push(e.message))
try{
 await page.goto('http://127.0.0.1:5174/?engine=clothcraft&techpackWorkspace=1',{waitUntil:'domcontentloaded',timeout:30000})
 await page.locator('[data-techpack-sheet="patterns"]').waitFor({timeout:25000})
 await page.getByRole('button',{name:'Add custom page'}).evaluate(n=>n.click())
 const custom=page.locator('[data-custom-blank=true]').last()
 await custom.waitFor({timeout:16000})
 await page.getByRole('button',{name:'Insert Excel table widget'}).evaluate(n=>n.click())
 const grid=custom.locator('.tps').first()
 await grid.waitFor({timeout:16000})
 const count=await grid.locator('th.tps-colhead').count()
 assert.equal(count,2)
 await grid.getByLabel('Table style').selectOption('dark')
 await page.waitForTimeout(110)
 assert.equal(await grid.getByLabel('Table style').inputValue(),'dark')
 await grid.getByRole('button',{name:'+ Column'}).click()
 assert.equal(await grid.locator('th.tps-colhead').count(),3)
 await grid.getByLabel('Column A title').fill('GRAPHIC REF')
 await grid.locator('td').first().dblclick({force:true})
 await grid.locator('.tps-editor').fill('CHEST LOGO')
 await grid.locator('.tps-editor').press('Enter')
 await page.waitForFunction(()=>document.querySelector('[data-custom-blank=true] .tps td')?.textContent?.trim()==='CHEST LOGO',null,{timeout:12000})
 await page.getByRole('button',{name:'Select tool'}).evaluate(n=>n.click())
 page.on('dialog',dlg=>dlg.accept('Excel dark Techpack widget'))
 await page.getByRole('button',{name:'Save template with my content'}).evaluate(n=>n.click())
 await page.waitForTimeout(300)
 const saved=await page.evaluate(()=>JSON.parse(localStorage.getItem('exo.techpack.user-templates.v1')||'[]'))
 const found=saved.find(item=>item.name==='Excel dark Techpack widget')
 assert(found)
 const stored=found.pageSnapshot.boxes[0].slot.spreadsheetTable
 assert.equal(stored.tableStyle.theme,'dark')
 assert.equal(stored.columns[0].label,'GRAPHIC REF')
 assert.equal(stored.columns.length,3)
 assert.equal(stored.rows[0].cells[stored.columns[0].id].input,'CHEST LOGO')
 await page.getByRole('tab',{name:'Templates'}).click()
 await page.getByRole('button',{name:'Open Saved presets templates'}).click()
 await page.locator('.tpws-template-card').filter({hasText:'Excel dark Techpack widget'}).first().getByRole('button',{name:'New artboard'}).evaluate(n=>n.click())
 await page.waitForFunction(()=>document.querySelectorAll('[data-custom-blank=true]').length>=2,null,{timeout:20000})
 await page.getByRole('button',{name:'Content edit mode'}).evaluate(n=>n.click())
 const cloned=page.locator('[data-custom-blank=true]').last().locator('.tps').first()
 await cloned.waitFor({timeout:12000})
 assert.equal(await cloned.getByLabel('Table style').inputValue(),'dark')
 assert.equal(await cloned.locator('th.tps-colhead').count(),3)
 assert.equal(await cloned.getByLabel('Column A title').inputValue(),'GRAPHIC REF')
 assert.equal((await cloned.locator('td').first().innerText()).trim(),'CHEST LOGO')
 assert.deepEqual(errors,[])
 console.log('PASS_EXCEL_WIDGET_THEME_TEMPLATE',JSON.stringify({columns:3,theme:'dark',customHeader:'GRAPHIC REF',authoredCell:'CHEST LOGO',errorCount:errors.length}))
}catch(e){console.error('FAIL_EXCEL_WIDGET_THEME_TEMPLATE',e.message,'JS_ERRORS',JSON.stringify(errors));process.exitCode=1}
finally{await browser.close()}
